    e.preventDefault();
    const cleanCnpj = cnpjInput.replace(/[^\d]/g, '');

    if (cleanCnpj.length === 14) {
      navigate(`/${cleanCnpj}`);
    } else {
      setError('CNPJ inválido. Digite os 14 dígitos.');
