export const CnpjSearch: React.FC = () => {
  const { cnpj: cnpjParam } = useParams();
  const navigate = useNavigate();
  const [cnpjInput, setCnpjInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [data, setData] = useState<CompanyData | null>(null);

  const formatCnpj = (v: string) => v.replace(/\D/g, '').replace(/^(\d{2})(\d)/, '$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3').replace(/\.(\d{3})(\d)/, '.$1/$2').replace(/(\d{4})(\d)/, '$1-$2').substring(0, 18);

  const performSearch = async (cnpjToSearch: string) => {
    const clean = cnpjToSearch.replace(/[^\d]/g, '');
    if (clean.length !== 14) { setError('Digite os 14 dígitos do CNPJ.'); return; }
    setLoading(true); setError(null); setData(null);
    try {
      const result = await fetchCompanyByCnpj(clean);
      setData(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erro ao buscar dados.');
    } finally { setLoading(false); }
  };

  useEffect(() => {
    if (cnpjParam) {
      const clean = cnpjParam.replace(/[^\d]/g, '');
      if (clean.length === 14) performSearch(clean);
    } else {
      setData(null); setCnpjInput(''); setError(null);
    }
  }, [cnpjParam]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const clean = cnpjInput.replace(/[^\d]/g, '');
    if (clean.length === 14) navigate(`/${clean}`);
    else setError('CNPJ inválido.');
  };

  return (
    <div className="space-y-8 w-full mx-auto pb-16 animate-in fade-in duration-500">
      {/* Hero & Search Section */}
      <div className={`text-center space-y-6 transition-all duration-700 ${data ? 'pt-2 pb-4' : 'pt-12 pb-12'}`}>
        <div className="space-y-2">
          <h1 className={`font-black tracking-tighter text-slate-900 dark:text-white uppercase leading-none transition-all ${data ? 'text-2xl' : 'text-4xl md:text-6xl'}`}>
            Consulta <span className="text-emerald-600">CNPJ</span> Grátis
          </h1>
          {!data && (
            <p className="text-slate-500 dark:text-slate-400 text-lg font-medium max-w-2xl mx-auto">
              Acesse dados da Receita Federal e Simples Nacional instantaneamente.
            </p>
          )}
        </div>

        <div className="max-w-3xl mx-auto relative group">
          <div className="absolute -inset-1 bg-gradient-to-r from-emerald-500 to-blue-600 rounded-2xl blur opacity-20 group-hover:opacity-40 transition duration-500"></div>
          <div className="relative bg-white dark:bg-slate-900 p-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-xl">
            <form onSubmit={handleSubmit} className="flex flex-col md:flex-row gap-2">
              <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
                <input
                  type="text"
                  value={cnpjInput}
                  onChange={(e) => setCnpjInput(formatCnpj(e.target.value))}
                  placeholder="00.000.000/0000-00"
                  className="w-full h-14 rounded-xl border-2 border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/50 px-4 pl-12 text-lg font-bold placeholder:text-slate-400 focus:border-emerald-500 focus:outline-none transition-all dark:text-white"
                />
              </div>
              <button disabled={loading} className="h-14 px-10 rounded-xl bg-emerald-600 text-white font-black uppercase tracking-widest hover:bg-emerald-700 disabled:opacity-50 transition-all flex items-center justify-center">
                {loading ? <Loader2 className="animate-spin h-6 w-6" /> : 'Buscar'}
              </button>
            </form>
          </div>
        </div>

        {error && (
          <div className="max-w-xl mx-auto bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/30 p-4 rounded-xl text-red-600 dark:text-red-400 text-sm font-bold flex items-center gap-3">
            <AlertCircle className="h-5 w-5 shrink-0" /> {error}
          </div>
        )}
      </div>

      {data ? (
        <div className="animate-in slide-in-from-bottom-4 duration-700">
          <CompanyDetails data={data} />
        </div>
      ) : !loading && (
        <div className="space-y-16">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <HomePromoBanner />
            <SMBHomeBanner />
          </div>

          <div className="grid gap-8 md:grid-cols-3">
            <div className="p-8 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm hover:shadow-md transition-shadow">
              <Zap className="h-8 w-8 text-emerald-600 mb-6" />
